function mapQuote(response,input,now=Date.now()){
 const fail=(code,retryable=false)=>({schema:'cdf-n8n-quote.v1',state:'rejected',code,retryable,evidenceRetrieved:false,paymentAttempted:false,handoff:null});
 if(!response||response.error||!Number.isInteger(response.statusCode))return fail('transport_error',true);
 let b;try{b=typeof response.body==='string'?JSON.parse(response.body):response.body}catch{return fail('response_not_json')}
 if(!b||typeof b!=='object'||Array.isArray(b))return fail('response_contract_invalid');
 if(b.charged!==false)return fail('no_charge_contract_missing');
 if(response.statusCode!==200)return {...fail(typeof b.error==='string'?b.error:'quote_not_ready',response.statusCode===429||response.statusCode>=500),httpStatus:response.statusCode,missing:Array.isArray(b.missing)?b.missing:[]};
 if(b.schema_version!=='civicdataforge.agent-quote.v1'||b.input_contract_version!=='civicdataforge.evidence-input.v2'||b.task!==input.task||b.quote_state!=='READY'||!/^cdfq_[a-f0-9]{24}$/.test(b.quote_id||''))return fail('response_contract_invalid');
 const issued=typeof b.issued_at==='string'?Date.parse(b.issued_at):NaN,expires=typeof b.expires_at==='string'?Date.parse(b.expires_at):NaN;
 if(!Number.isFinite(issued)||!Number.isFinite(expires)||issued>now+60000||expires<=now||expires<=issued||expires-issued>900001)return fail('quote_time_invalid');
 if(!b.purchase||b.purchase.store_url!=='https://apify.com/civicdataforge/civicdataforge-evidence-gateway')return fail('purchase_destination_invalid');
 return {schema:'cdf-n8n-quote.v1',state:'scope_ready_not_evidence',paymentAttempted:false,evidenceRetrieved:false,quoteId:b.quote_id,issuedAt:b.issued_at,expiresAt:b.expires_at,submittedScope:input,scopeBinding:'Locally bound to the submitted input; quote response does not echo the address. Re-run after any input change.',handoff:{url:b.purchase.store_url,automaticPurchase:false,instruction:'Review the current live price and input in the separate paid route. Explicitly authorize purchase there. A quote is not permit evidence or a compliance decision.'}};
}
const rows=$input.all();if(rows.length!==1)throw new Error('Exactly one response required');return [{json:mapQuote(rows[0].json,$('Choose input').first().json),pairedItem:{item:0}}];
